/**
 * Called from bonds/index.ts during setupProviders(). The i18n
 * provider was already wired at module-eval time above — this
 * function exists for compat with the legacy bond-setup contract
 * and is a no-op.
 */
export function setupI18nDefault(): void {
  // intentionally empty
}
